 const [viewMode,setViewMode]=useState<'overview'|'walk'>('overview'),[arranging,setArranging]=useState(false),[moveTarget,setMoveTarget]=useState<MoveTarget|null>(null),[roomListHidden,setRoomListHidden]=useState(false);
 const weather=useWeather(userKey,signedIn);
 const [panel,setPanel]=useState<Panel>(null),[roomId,setRoomId]=useState<string|null>(null),[highlight,setHighlight]=useState<string|null>(null),[inspect,setInspect]=useState(false),[camera,setCamera]=useState<Camera>({yaw:-.45,pitch:.55,zoom:1});
 const [draft,setDraft]=useState<KnowledgeObject|null>(null),draftRef=useRef(draft),[editorReadOnly,setEditorReadOnly]=useState(false),[draftStatus,setDraftStatus]=useState(''),savedDraft=useRef(''),[recover,setRecover]=useState<KnowledgeObject|null>(null),draftKey=`idea-grove-draft-v1-${userKey}`;
 const [saving,setSaving]=useState(false),[toast,setToast]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('unplaced'),[tagFilter,setTagFilter]=useState(''),[tagEdit,setTagEdit]=useState<Tag|null>(null),[furnitureEdit,setFurnitureEdit]=useState<Furniture|null>(null),[placementRoom,setPlacementRoom]=useState(''),[placementFurniture,setPlacementFurniture]=useState(''),[confirm,setConfirm]=useState<{text:string;run:()=>void}|null>(null),[importWorld,setImportWorld]=useState<World|null>(null),[roomName,setRoomName]=useState(''),[mergeRoom,setMergeRoom]=useState('');
 const modalRef=useRef<HTMLDivElement>(null),historyRequest=useRef(0);
