 const load=useCallback(async()=>{if(!signedIn){setLoaded(true);return;}try{const r=await fetch('/api/world',{cache:'no-store'}),d=await r.json() as ApiPayload;if(!r.ok)throw new Error(d.error||'Could not load your world.');setOwn(d.world);ownRef.current=d.world;revision.current=d.revision;setLoaded(true);setLoadError(false);if(d.world.objects.length)setDemo(false);}catch(e){setLoadError(true);setLoaded(true);notify(e instanceof Error?e.message:'Could not load your world.');}},[signedIn,notify]);
