 const closeEditor=useCallback(()=>{const d=draftRef.current;if(d&&!editorReadOnly&&JSON.stringify(d)!==savedDraft.current)void persistDraft(d);setDraft(null);},[editorReadOnly,persistDraft]);
 const capture=useCallback((kind:'memo'|'book')=>{try{const pending=localStorage.getItem(draftKey);if(pending){const old=JSON.parse(pending) as KnowledgeObject;if(old.id!==draftRef.current?.id){setDemo(false);setHistorical(null);setEditorReadOnly(false);savedDraft.current='';setDraft(old);notify('Resumed your unsent draft. Save it before starting another thought.');return;}}}catch{}setDemo(false);setHistorical(null);setHistoryRevision(null);historyRequest.current++;setHistoryLoading(false);setEditorReadOnly(false);setRoomId(null);savedDraft.current='';const now=new Date().toISOString();const d:KnowledgeObject={id:uid(),kind,title:'',content:'',tags:[],archived:false,createdAt:now,updatedAt:now};setDraft(d);setPlacementRoom('');setPlacementFurniture('');if(signedIn)void persistDraft(d);},[signedIn,persistDraft,draftKey,notify]);
