 useEffect(()=>{const key=(e:KeyboardEvent)=>{const el=e.target as HTMLElement;if(el.matches('input,textarea,select,[contenteditable]'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setPanel('inbox');setTimeout(()=>document.getElementById('library-search')?.focus(),20);}else if(e.key.toLowerCase()==='n'&&!e.metaKey&&!e.ctrlKey&&!e.altKey){e.preventDefault();capture(e.shiftKey?'book':'memo');}else if(e.key==='Escape'){if(arranging){setArranging(false);setMoveTarget(null);return;}if(viewMode==='walk'&&(document.pointerLockElement||document.activeElement?.classList.contains('walk-canvas')))return;if(confirm)setConfirm(null);else if(draft)closeEditor();else {setPanel(null);setRoomId(null);}}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[capture,closeEditor,draft,confirm,viewMode,arranging]);
 useEffect(()=>{const fn=(e:BeforeUnloadEvent)=>{if((draftRef.current&&!editorReadOnly&&JSON.stringify(draftRef.current)!==savedDraft.current)||saving){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',fn);return()=>window.removeEventListener('beforeunload',fn);},[editorReadOnly,saving]);
 useEffect(()=>{if(!draft&&!confirm)return;const prev=document.activeElement as HTMLElement;const el=modalRef.current;const timer=setTimeout(()=>el?.querySelector<HTMLElement>('input,button')?.focus(),40);const trap=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();if(confirm)setConfirm(null);else closeEditor();}if(e.key==='Tab'){const nodes=el?.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,select,a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};el?.addEventListener('keydown',trap);return()=>{clearTimeout(timer);el?.removeEventListener('keydown',trap);prev?.focus();};},[!!draft,!!confirm,closeEditor]);
 useEffect(()=>{setRoomName(room?.name??'');setMergeRoom('');},[room?.id,room?.name]);
