 const historyAt=async(value:number)=>{if(demo){setDemoStage(value);return;}const serial=++historyRequest.current;if(value===revision.current){setHistoryLoading(false);setHistorical(null);setHistoryRevision(null);return;}setHistoryLoading(true);try{const r=await fetch(`/api/history?revision=${value}`,{cache:'no-store'}),d=await r.json() as ApiPayload;if(!r.ok)throw new Error(d.error);if(serial===historyRequest.current){setHistorical(d.world);setHistoryRevision(value);setRoomId(null);}}catch(e){notify(e instanceof Error?e.message:'Could not reconstruct this moment.');}finally{if(serial===historyRequest.current)setHistoryLoading(false);}};
 const enterRoom=(id:string)=>{setArranging(false);setMoveTarget(null);setRoomId(id);setPanel(null);setHighlight(null);setCamera({yaw:-.5,pitch:.6,zoom:1});};
