 const place=async(objectId:string,furnitureId:string)=>{if(!guard())return;await commit([{type:'placement.put',placement:{id:uid(),objectId,furnitureId}}]);};
 const visibleObjects=world.objects.filter(o=>{const placed=world.placements.some(p=>p.objectId===o.id);return(filter==='archived'?o.archived:!o.archived)&&(filter!=='unplaced'||!placed)&&(filter!=='untagged'||!o.tags.length)&&(filter!=='books'||o.kind==='book')&&(!tagFilter||o.tags.includes(tagFilter))&&(!query||(o.title+' '+o.content).toLowerCase().includes(query.toLowerCase()));}).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
